mod digest_rules;

use digest_rules::{format_message, should_include};
use std::fs;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.split_terminator('\n');
    let title = lines.next().unwrap_or("");
    let count: usize = lines.next().unwrap_or("0").parse().unwrap();
    let min_priority: i64 = lines.next().unwrap_or("0").parse().unwrap();
    let mut contents = format!("{title}\n");
    let mut saved = 0;
    let mut characters = 0;
    for index in 1..=count {
        let record = lines.next().unwrap_or("");
        let (priority, message) = record.split_once('|').unwrap();
        let priority: i64 = priority.parse().unwrap();
        if should_include(priority, min_priority) {
            contents.push_str(&format_message(index, priority, message));
            contents.push('\n');
            saved += 1;
            characters += message.chars().count();
        }
    }
    fs::write("priority_digest.txt", contents).unwrap();
    println!("saved={saved}|skipped={}|characters={characters}", count - saved);
}

