pub fn available_stock(stock: i64, reserved: i64, mode: &str) -> i64 {
    if mode == "urgent" {
        stock
    } else {
        (stock - reserved).max(0)
    }
}

mod inventory;

use inventory::available_stock;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let stock: i64 = lines.next().unwrap().parse().unwrap();
    let demand: i64 = lines.next().unwrap().parse().unwrap();
    let reserved: i64 = lines.next().unwrap().parse().unwrap();
    let mode = lines.next().unwrap();
    let available = available_stock(stock, reserved, mode);
    let fulfilled = demand.min(available);
    let backorder = demand - fulfilled;
    let remaining = available - fulfilled;
    println!("fulfilled={fulfilled}|backorder={backorder}|remaining={remaining}");
}

source_texts.incident_routing_repo:
mod routing;

use routing::channel_for;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let (mut email, mut chat, mut pager) = (0, 0, 0);
    for _ in 0..count {
        let mut parts = lines.next().unwrap().splitn(3, '|');
        let team = parts.next().unwrap();
        let severity = parts.next().unwrap();
        let after_hours = parts.next().unwrap();
        let channel = channel_for(severity, after_hours);
        match channel {
            "email" => email += 1,
            "chat" => chat += 1,
            "pager" => pager += 1,
            _ => unreachable!(),
        }
        println!("{team}:{channel}");
    }
    println!("email={email},chat={chat},pager={pager}");
}

pub fn channel_for(severity: &str, after_hours: &str) -> &'static str {
    match severity {
        "low" => "email",
        "high" if after_hours == "yes" => "pager",
        "high" => "chat",
        "critical" => "pager",
        _ => "email",
    }
}

source_texts.ledger_reconciliation_repo:
pub fn absolute_difference(expected: i64, actual: i64) -> i64 {
    (expected - actual).abs()
}

pub fn is_within_tolerance(difference: i64, tolerance: i64) -> bool {
    difference <= tolerance
}

mod ledger;

use ledger::{absolute_difference, is_within_tolerance};
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let tolerance: i64 = lines.next().unwrap().parse().unwrap();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let (mut matched, mut unmatched, mut variance) = (0, 0, 0);
    for _ in 0..count {
        let mut parts = lines.next().unwrap().split('|');
        let id = parts.next().unwrap();
        let expected: i64 = parts.next().unwrap().parse().unwrap();
        let actual: i64 = parts.next().unwrap().parse().unwrap();
        let difference = absolute_difference(expected, actual);
        variance += difference;
        if is_within_tolerance(difference, tolerance) {
            matched += 1;
            println!("{id}:match");
        } else {
            unmatched += 1;
            println!("{id}:diff={difference}");
        }
    }
    println!("matched={matched},unmatched={unmatched},variance={variance}");
}

