mod routing;

use routing::channel_for;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let (mut email, mut chat, mut pager) = (0, 0, 0);
    for _ in 0..count {
        let mut parts = lines.next().unwrap().splitn(3, '|');
        let team = parts.next().unwrap();
        let severity = parts.next().unwrap();
        let after_hours = parts.next().unwrap();
        let channel = channel_for(severity, after_hours);
        match channel {
            "email" => email += 1,
            "chat" => chat += 1,
            "pager" => pager += 1,
            _ => unreachable!(),
        }
        println!("{team}:{channel}");
    }
    println!("email={email},chat={chat},pager={pager}");
}

incident_routing_repo.routing.rs:
pub fn channel_for(severity: &str, after_hours: &str) -> &'static str {
    match severity {
        "low" => "email",
        "high" if after_hours == "yes" => "pager",
        "high" => "chat",
        "critical" => "pager",
        _ => "email",
    }
}

