from sla import due_minutes

priority = input()
tier = input()
after_hours = input()
print(f"due_minutes={due_minutes(priority, tier, after_hours)}|tier={tier}")

def due_minutes(priority: str, tier: str, after_hours: str) -> int:
    base_minutes = {
        "normal": 480,
        "high": 120,
        "critical": 30,
    }[priority]
    if tier == "premium":
        base_minutes = max(15, base_minutes - 30)
    if after_hours == "yes":
        base_minutes += 60
    return base_minutes

