mod rollout;

use rollout::is_eligible;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let mut allowed = 0;
    for _ in 0..count {
        let mut parts = lines.next().unwrap().split('|');
        let user = parts.next().unwrap();
        let plan = parts.next().unwrap();
        let country = parts.next().unwrap();
        let eligible = is_eligible(plan, country);
        if eligible {
            allowed += 1;
        }
        println!("{user}:{}", if eligible { "allow" } else { "deny" });
    }
    println!("allowed={allowed},denied={}", count - allowed);
}

pub fn is_eligible(plan: &str, country: &str) -> bool {
    plan == "enterprise" || (plan == "pro" && country != "blocked")
}

