pub fn absolute_difference(expected: i64, actual: i64) -> i64 {
    (expected - actual).abs()
}

pub fn is_within_tolerance(difference: i64, tolerance: i64) -> bool {
    difference <= tolerance
}

mod ledger;

use ledger::{absolute_difference, is_within_tolerance};
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let tolerance: i64 = lines.next().unwrap().parse().unwrap();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let mut matched = 0;
    let mut variance = 0;
    for _ in 0..count {
        let mut parts = lines.next().unwrap().split('|');
        let id = parts.next().unwrap();
        let expected: i64 = parts.next().unwrap().parse().unwrap();
        let actual: i64 = parts.next().unwrap().parse().unwrap();
        let difference = absolute_difference(expected, actual);
        variance += difference;
        if is_within_tolerance(difference, tolerance) {
            matched += 1;
            println!("{id}:match");
        } else {
            println!("{id}:diff={difference}");
        }
    }
    println!("matched={matched},unmatched={},variance={variance}", count - matched);
}

source_texts.priority_digest_repo:
pub fn should_include(priority: i64, min_priority: i64) -> bool {
    priority >= min_priority
}

pub fn format_message(index: usize, priority: i64, message: &str) -> String {
    format!("{index}|{priority}|{message}")
}

mod digest_rules;

use digest_rules::{format_message, should_include};
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.split_terminator('\n');
    let title = lines.next().unwrap_or("");
    let count: usize = lines.next().unwrap_or("0").parse().unwrap();
    let min_priority: i64 = lines.next().unwrap_or("0").parse().unwrap();
    let mut contents = format!("{title}\n");
    let mut saved = 0;
    let mut characters = 0;
    for offset in 0..count {
        let line = lines.next().unwrap_or("");
        let (priority, message) = line.split_once('|').unwrap();
        let priority: i64 = priority.parse().unwrap();
        if should_include(priority, min_priority) {
            contents.push_str(&format_message(offset + 1, priority, message));
            contents.push('\n');
            saved += 1;
            characters += message.chars().count();
        }
    }
    std::fs::write("priority_digest.txt", contents).unwrap();
    println!("saved={saved}|skipped={}|characters={characters}", count - saved);
}

