use sla::due_minutes;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let priority = lines.next().unwrap_or("");
    let tier = lines.next().unwrap_or("");
    let after_hours = lines.next().unwrap_or("");
    println!("due_minutes={}|tier={tier}", due_minutes(priority, tier, after_hours));
}

pub fn due_minutes(priority: &str, tier: &str, after_hours: &str) -> i64 {
    let base = match priority {
        "high" => 120,
        "critical" => 30,
        _ => 480,
    };
    let adjusted = if tier == "premium" {
        (base - 30).max(15)
    } else {
        base
    };
    if after_hours == "yes" {
        adjusted + 60
    } else {
        adjusted
    }
}

source_texts.incident_routing_repo:
mod routing;

use routing::channel_for;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let mut email = 0;
    let mut chat = 0;
    let mut pager = 0;
    for _ in 0..count {
        let mut parts = lines.next().unwrap().split('|');
        let team = parts.next().unwrap();
        let severity = parts.next().unwrap();
        let after_hours = parts.next().unwrap();
        let channel = channel_for(severity, after_hours);
        match channel {
            "email" => email += 1,
            "chat" => chat += 1,
            _ => pager += 1,
        }
        println!("{team}:{channel}");
    }
    println!("email={email},chat={chat},pager={pager}");
}

pub fn channel_for(severity: &str, after_hours: &str) -> &'static str {
    match severity {
        "low" => "email",
        "high" if after_hours == "yes" => "pager",
        "high" => "chat",
        _ => "pager",
    }
}

source_texts.inventory_reservation_repo:
pub fn available_stock(stock: i64, reserved: i64, mode: &str) -> i64 {
    if mode == "urgent" {
        stock
    } else {
        (stock - reserved).max(0)
    }
}

mod inventory;

use inventory::available_stock;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let stock: i64 = lines.next().unwrap().parse().unwrap();
    let demand: i64 = lines.next().unwrap().parse().unwrap();
    let reserved: i64 = lines.next().unwrap().parse().unwrap();
    let mode = lines.next().unwrap();
    let available = available_stock(stock, reserved, mode);
    let fulfilled = demand.min(available);
    let backorder = demand - fulfilled;
    let remaining = available - fulfilled;
    println!("fulfilled={fulfilled}|backorder={backorder}|remaining={remaining}");
}

