use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.split_terminator('\n');
    let title = lines.next().unwrap_or("");
    let count: usize = lines.next().unwrap_or("0").parse().unwrap();
    let min_length: usize = lines.next().unwrap_or("0").parse().unwrap();
    let mut contents = format!("{title}\n");
    let mut saved = 0;
    let mut characters = 0;
    for index in 1..=count {
        let entry = lines.next().unwrap_or("");
        if should_include(entry, min_length) {
            contents.push_str(&format_entry(index, entry));
            contents.push('\n');
            saved += 1;
            characters += entry.chars().count();
        }
    }
    fs::write("filtered_report.txt", contents).unwrap();
    println!(
        "saved={saved}|skipped={}|characters={characters}",
        count - saved
    );
}

