mod report_rules;

use report_rules::{format_entry, should_include};
use std::fs;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.split_terminator('\n');
    let title = lines.next().unwrap_or("");
    let count: usize = lines.next().unwrap_or("0").parse().unwrap();
    let min_length: usize = lines.next().unwrap_or("0").parse().unwrap();
    let entries: Vec<&str> = (0..count).map(|_| lines.next().unwrap_or("")).collect();
    let mut contents = format!("{title}\n");
    let mut saved = 0;
    let mut characters = 0;
    for (offset, entry) in entries.iter().enumerate() {
        if should_include(entry, min_length) {
            contents.push_str(&format_entry(offset + 1, entry));
            contents.push('\n');
            saved += 1;
            characters += entry.chars().count();
        }
    }
    fs::write("filtered_report.txt", contents).unwrap();
    println!(
        "saved={saved}|skipped={}|characters={characters}",
        count - saved
    );
}

pub fn should_include(entry: &str, min_length: usize) -> bool {
    entry.chars().count() >= min_length
}

pub fn format_entry(index: usize, entry: &str) -> String {
    format!("{index}|{entry}")
}

source_texts.ledger_reconciliation_repo:
pub fn absolute_difference(expected: i64, actual: i64) -> i64 {
    (expected - actual).abs()
}

pub fn is_within_tolerance(difference: i64, tolerance: i64) -> bool {
    difference <= tolerance
}

mod ledger;

use ledger::{absolute_difference, is_within_tolerance};
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let tolerance: i64 = lines.next().unwrap().parse().unwrap();
    let count: usize = lines.next().unwrap().parse().unwrap();
    let (mut matched, mut unmatched, mut variance) = (0, 0, 0);
    for _ in 0..count {
        let mut parts = lines.next().unwrap().splitn(3, '|');
        let id = parts.next().unwrap();
        let expected: i64 = parts.next().unwrap().parse().unwrap();
        let actual: i64 = parts.next().unwrap().parse().unwrap();
        let difference = absolute_difference(expected, actual);
        variance += difference;
        if is_within_tolerance(difference, tolerance) {
            matched += 1;
            println!("{id}:match");
        } else {
            unmatched += 1;
            println!("{id}:diff={difference}");
        }
    }
    println!("matched={matched},unmatched={unmatched},variance={variance}");
}

