use sla::due_minutes;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let priority = lines.next().unwrap_or("");
    let tier = lines.next().unwrap_or("");
    let after_hours = lines.next().unwrap_or("");
    println!(
        "due_minutes={}|tier={tier}",
        due_minutes(priority, tier, after_hours)
    );
}

pub fn due_minutes(priority: &str, tier: &str, after_hours: &str) -> i64 {
    let base = match priority {
        "high" => 120,
        "critical" => 30,
        _ => 480,
    };
    let adjusted = if tier == "premium" {
        (base - 30).max(15)
    } else {
        base
    };
    if after_hours == "yes" {
        adjusted + 60
    } else {
        adjusted
    }
}

