pub fn delivery_quote(distance: u64, base: u64, per_km: u64, service: &str) -> u64 {
    let service_fee = if service == "express" { 300 } else { 0 };
    let distance_fee = if distance > 100 { 500 } else { 0 };
    base + distance * per_km + service_fee + distance_fee
}

