pub fn available_stock(stock: u64, reserved: u64, mode: &str) -> u64 {
    if mode == "urgent" {
        stock
    } else {
        stock.saturating_sub(reserved)
    }
}

mod inventory;

use inventory::available_stock;
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.lines();
    let stock: u64 = lines.next().unwrap().parse().unwrap();
    let demand: u64 = lines.next().unwrap().parse().unwrap();
    let reserved: u64 = lines.next().unwrap().parse().unwrap();
    let mode = lines.next().unwrap();
    let available = available_stock(stock, reserved, mode);
    let fulfilled = demand.min(available);
    let backorder = demand - fulfilled;
    let remaining = available - fulfilled;
    println!("fulfilled={fulfilled}|backorder={backorder}|remaining={remaining}");
}

