pub fn should_include(priority: u64, min_priority: u64) -> bool {
    priority >= min_priority
}

pub fn format_message(index: usize, priority: u64, message: &str) -> String {
    format!("{index}|{priority}|{message}")
}

mod digest_rules;

use digest_rules::{format_message, should_include};
use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut lines = input.split_terminator('\n');
    let title = lines.next().unwrap_or("");
    let count: usize = lines.next().unwrap_or("0").parse().unwrap();
    let min_priority: u64 = lines.next().unwrap_or("0").parse().unwrap();
    let mut contents = format!("{title}\n");
    let (mut saved, mut characters) = (0, 0);
    for offset in 0..count {
        let line = lines.next().unwrap_or("");
        let (priority, message) = line.split_once('|').unwrap();
        let priority: u64 = priority.parse().unwrap();
        if should_include(priority, min_priority) {
            contents.push_str(&format_message(offset + 1, priority, message));
            contents.push('\n');
            saved += 1;
            characters += message.chars().count();
        }
    }
    std::fs::write("priority_digest.txt", contents).unwrap();
    println!(
        "saved={saved}|skipped={}|characters={characters}",
        count - saved
    );
}

