    team, severity, after_hours = input().split("|")
    channel = channel_for(severity, after_hours)
    counts[channel] += 1
    print(f"{team}:{channel}")
print(f"email={counts['email']},chat={counts['chat']},pager={counts['pager']}")

def channel_for(severity: str, after_hours: str) -> str:
    if severity == "low":
        return "email"
    if severity == "high" and after_hours == "no":
        return "chat"
    return "pager"

